import json
import os
import urllib.parse
import urllib.request

# Allow deployments to supply the live service endpoint if it has moved.
BASE = os.environ.get("PRICES_BASE_URL", "http://prices.internal/api/v1/price").rstrip("/")


def get_price(sku: str) -> float:
    url = f"{BASE}/{urllib.parse.quote(sku, safe='')}"
    with urllib.request.urlopen(url, timeout=5) as response:
        return float(json.load(response)["price"])


def get_total(skus: list) -> float:
    return sum((get_price(sku) for sku in skus), 0.0)
